            if (supportCase.Summary.Length < 8) return "detail-required";
            _triage[supportCase.Reference] = supportCase.SecurityRelated ? "security" : "standard";
            return "triaged";
        }

        public string Retriage(SupportCase supportCase, string newProduct, string reason)
        {
            if (string.IsNullOrWhiteSpace(supportCase.Reference)) return "invalid-reference";
            if (!_triage.ContainsKey(supportCase.Reference)) return "not-triaged";
            if (string.IsNullOrWhiteSpace(newProduct)) return "product-required";
            if (newProduct == supportCase.Product) return "unchanged";
            if (string.IsNullOrWhiteSpace(reason)) return "reason-required";
            if (supportCase.SecurityRelated && reason == "deprioritise") return "security-block";
            if (supportCase.ReopenCount > 3 && reason == "duplicate") return "manager-review";
            _triage[supportCase.Reference] = "retriaged:" + newProduct;
            return "retriaged";
        }
    }

    private sealed class DeadlineOperations
    {
        private readonly Dictionary<string, int> _deadlines = new(StringComparer.Ordinal);

        public string SetDeadline(SupportCase supportCase, ServicePolicy policy, int openedMinute, bool weekend)
        {
            if (string.IsNullOrWhiteSpace(supportCase.Reference)) return "invalid-reference";
            if (policy.Product != supportCase.Product) return "policy-mismatch";
            if (openedMinute < 0) return "invalid-opened-minute";
            if (policy.StandardMinutes <= 0) return "invalid-standard-sla";
            if (policy.PriorityMinutes <= 0) return "invalid-priority-sla";
            if (weekend && !policy.WeekendCover) return "next-business-window";
            var duration = supportCase.SecurityRelated ? policy.PriorityMinutes : policy.StandardMinutes;
            _deadlines[supportCase.Reference] = openedMinute + duration;
            return "deadline-set";
        }

        public string CheckDeadline(SupportCase supportCase, int currentMinute, int warningWindow)
        {
            if (string.IsNullOrWhiteSpace(supportCase.Reference)) return "invalid-reference";
            if (!_deadlines.ContainsKey(supportCase.Reference)) return "deadline-missing";
            if (currentMinute < 0) return "invalid-current-minute";
            if (warningWindow < 0) return "invalid-warning-window";
            if (currentMinute > _deadlines[supportCase.Reference]) return "breached";
            if (currentMinute == _deadlines[supportCase.Reference]) return "due-now";
            if (_deadlines[supportCase.Reference] - currentMinute <= warningWindow) return "warning";
            _deadlines[supportCase.Reference] = Math.Max(currentMinute, _deadlines[supportCase.Reference]);
            return supportCase.SecurityRelated ? "on-track-security" : "on-track";
        }
    }

    private sealed class AssignmentOperations
    {
        private readonly Dictionary<string, string> _assignments = new(StringComparer.Ordinal);

        public string Assign(SupportCase supportCase, IEnumerable<Agent> agents, string requiredSkill)
        {
            if (string.IsNullOrWhiteSpace(supportCase.Reference)) return "invalid-reference";
            if (string.IsNullOrWhiteSpace(requiredSkill)) return "skill-required";
            var eligible = agents.Where(agent => agent.Available).ToList();
            if (eligible.Count == 0) return "no-available-agent";
            eligible = eligible.Where(agent => agent.Skills.Contains(requiredSkill)).ToList();
            if (eligible.Count == 0) return "no-skilled-agent";
            if (supportCase.SecurityRelated) eligible = eligible.Where(agent => agent.Skills.Contains("security")).ToList();
            if (eligible.Count == 0) return "no-security-agent";
            if (supportCase.CustomerTier == "premium") eligible = eligible.Where(agent => agent.OpenCases < 8).ToList();
            if (eligible.Count == 0) return "capacity-exhausted";
            var selected = eligible.OrderBy(agent => agent.OpenCases).ThenBy(agent => agent.Id).First();
            _assignments[supportCase.Reference] = selected.Id;
            return selected.Id;
        }

        public string Reassign(SupportCase supportCase, Agent next, string reason)
        {
            if (string.IsNullOrWhiteSpace(supportCase.Reference)) return "invalid-reference";
            if (!_assignments.ContainsKey(supportCase.Reference)) return "assignment-missing";
            if (string.IsNullOrWhiteSpace(next.Id)) return "invalid-agent";
            if (!next.Available) return "agent-unavailable";
            if (next.OpenCases >= 12) return "agent-at-capacity";
            if (string.IsNullOrWhiteSpace(reason)) return "reason-required";
            if (supportCase.SecurityRelated && !next.Skills.Contains("security")) return "security-skill-required";
            _assignments[supportCase.Reference] = next.Id;
            return reason == "escalation" ? "reassigned-escalation" : "reassigned";
        }
    }

    private sealed class CommunicationOperations
    {
        private readonly Dictionary<string, string> _communications = new(StringComparer.Ordinal);

        public string RecordMessage(SupportCase supportCase, CustomerMessage message)
        {
            if (string.IsNullOrWhiteSpace(supportCase.Reference)) return "invalid-reference";
            if (message.Channel is not ("email" or "chat" or "phone")) return "invalid-channel";
            if (string.IsNullOrWhiteSpace(message.Body)) return "body-required";
            if (message.AttachmentCount < 0) return "invalid-attachment-count";
            if (message.AttachmentCount > 10) return "attachment-limit";
            if (message.ContainsSensitiveData && message.Channel == "chat") return "secure-channel-required";
            if (supportCase.SecurityRelated && message.Body.Length < 12) return "security-detail-required";
            _communications[supportCase.Reference] = message.Channel + ":" + message.Body.Length;
            return "recorded";
        }

        public string Escalate(SupportCase supportCase, EscalationRule rule, int ageMinutes)
        {
            if (string.IsNullOrWhiteSpace(supportCase.Reference)) return "invalid-reference";
            if (!_communications.ContainsKey(supportCase.Reference)) return "communication-required";
            if (string.IsNullOrWhiteSpace(rule.Code)) return "invalid-rule";
            if (string.IsNullOrWhiteSpace(rule.Destination)) return "destination-required";
            if (ageMinutes < 0) return "invalid-age";
            if (ageMinutes < rule.AgeMinutes) return "too-early";
            if (rule.SecurityOnly && !supportCase.SecurityRelated) return "rule-not-applicable";
            _communications[supportCase.Reference] = "escalated:" + rule.Destination;
            return "escalated";
        }
    }
